package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_equals_TriageGen2Test {

    @Test
    public void testEquals_SameInstance() {
        Element element = Parser.parseBodyFragment("<div></div>").body().child(0);
        // if (this == o) return true;
        Assert.assertTrue(element.equals(element));
    }

    @Test
    public void testEquals_Null() {
        Element element = Parser.parseBodyFragment("<div></div>").body().child(0);
        // if (o == null || getClass() != o.getClass()) return false;
        Assert.assertFalse(element.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        Element element = Parser.parseBodyFragment("<div></div>").body().child(0);
        String other = "not an element";
        // if (o == null || getClass() != o.getClass()) return false;
        Assert.assertFalse(element.equals(other));
    }

    @Test
    public void testEquals_SuperEqualsFalse() {
        // The implementation says: if (!super.equals(o)) return false;
        // In Jsoup, Node.equals (super) usually checks identity or specific properties.
        // To trigger this, we need two different Element objects that fail super.equals.
        Element element1 = Parser.parseBodyFragment("<div></div>").body().child(0);
        Element element2 = Parser.parseBodyFragment("<span></span>").body().child(0);

        Assert.assertFalse(element1.equals(element2));
    }

    @Test
    public void testEquals_IdentityCheckInImplementation() {
        // The provided implementation ends with: return this == o;
        // This is a very strange implementation (it effectively makes equals behave like == 
        // after passing the super.equals check), but we must test the logic provided.

        Element element1 = Parser.parseBodyFragment("<div></div>").body().child(0);

        // Even if they are "logically" similar, if they are different instances, 
        // the provided code 'return this == o' will return false.
        Element element2 = Parser.parseBodyFragment("<div></div>").body().child(0);

        // Note: element1.equals(element2) will likely fail at super.equals(o) 
        // or at the final 'return this == o' depending on Jsoup's Node.equals.
        Assert.assertFalse(element1.equals(element2));
    }
}
